-- Run in Supabase SQL editor. RLS remains default-deny; only the server uses its service-role key.
create table participants (id uuid primary key default gen_random_uuid(), full_name text not null, normalized_name text not null, nip text not null, unique_key text unique not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table campaigns (id uuid primary key default gen_random_uuid(), campaign_code text unique not null, title text not null, description text, status text not null check (status in ('draft','upcoming','active','archived','disabled')), start_at timestamptz, end_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table quests (id uuid primary key default gen_random_uuid(), quest_code text unique not null, title text not null, subtitle text, quest_type text not null, status text not null check (status in ('draft','upcoming','active','archived','disabled')), max_score integer not null, version integer not null default 1, allow_replay boolean default false, config_json jsonb not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table campaign_quests (id uuid primary key default gen_random_uuid(), campaign_id uuid references campaigns(id), quest_id uuid references quests(id), order_index integer not null, is_required boolean default true, unlock_rule text not null default 'sequential', prerequisite_quest_ids uuid[] default '{}', available_from timestamptz, available_until timestamptz, unique(campaign_id, quest_id));
create table participant_campaign_progress (id uuid primary key default gen_random_uuid(), participant_id uuid references participants(id), campaign_id uuid references campaigns(id), status text not null default 'not_started', completed_quest_count integer default 0, total_score integer default 0, max_score integer default 0, started_at timestamptz, completed_at timestamptz, updated_at timestamptz default now(), unique(participant_id,campaign_id));
create table participant_quest_progress (id uuid primary key default gen_random_uuid(), participant_id uuid references participants(id), campaign_id uuid references campaigns(id), quest_id uuid references quests(id), quest_version integer not null, status text not null, score integer, max_score integer, answer_data_json jsonb, started_at timestamptz, completed_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now(), unique(participant_id,campaign_id,quest_id,quest_version));
alter table participants enable row level security; alter table campaigns enable row level security; alter table quests enable row level security; alter table campaign_quests enable row level security; alter table participant_campaign_progress enable row level security; alter table participant_quest_progress enable row level security;
